{"content":"1|//! Persistent allocation of human-facing Incus names, not identity authority.
2|//! Never infer the counter from provider names. Creation intents fence POST
3|//! retries only; identity records and their UUIDs own subsequent lifecycle.
4|use super::*;
5|
6|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
7|#[serde(deny_unknown_fields)]
8|pub struct NativeCreationRequest {
9|    pub operation_id: String,
10|    pub actor_id: String,
11|    pub caller_session: String,
12|    pub caller_genesis: String,
13|    pub owner_kind: String,
14|    pub logical_target: String,
15|    pub schema_hash: String,
16|    pub request_digest: String,
17|    pub request_json: String,
18|}
19|
20|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
21|#[serde(deny_unknown_fields)]
22|pub struct NativeCreationRecord {
23|    pub request: NativeCreationRequest,
24|    pub number: i64,
25|    pub name: String,
26|    pub phase: String,
27|    pub native_uuid: String,
28|}
29|
30|pub fn is_numbered_native_name(name: &str) -> bool {
31|    name.strip_prefix("ID-").is_some_and(|number| {
32|        number.parse::<i64>().is_ok_and(|n| n > 0 && n.to_string() == number)
33|    })
34|}
35|
36|fn records(tx: &MultiTransaction) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
37|    query(tx, "?[document,operation_id] := *native_container_creations{document,operation_id}", Params::new())?
38|        .rows.iter().map(|row| {
39|            let record: NativeCreationRecord = serde_json::from_str(&string(row, 0)?)?;
40|            if string(row, 1)? != record.request.operation_id
41|                || record.request.schema_hash.is_empty()
42|                || !valid_root_repair_digest(&record.request.request_digest)
43|                || record.number <= 0 || record.name != format!("ID-{}", record.number)
44|                || !matches!(record.phase.as_str(), "intent" | "bound" | "complete")
45|                || (record.phase != "intent" && uuid::Uuid::parse_str(&record.native_uuid)
46|                    .map_or(true, |id| id.to_string() != record.native_uuid))
47|            {
48|                return Err(err("native creation journal is corrupt"));
49|            }
50|            Ok(record)
51|        }).collect()
52|}
53|
54|fn put(tx: &MultiTransaction, record: &NativeCreationRecord) -> std::result::Result<(), CozoError> {
55|    query(tx, "?[operation_id,document] <- [[$op,$doc]] :put native_container_creations {operation_id => document}",
56|        BTreeMap::from([
57|            ("op".into(), DataValue::Str(record.request.operation_id.as_str().into())),
58|            ("doc".into(), DataValue::Str(serde_json::to_string(record)?.into())),
59|        ]))?;
60|    Ok(())
61|}
62|
63|fn sequence(tx: &MultiTransaction, rows: &[NativeCreationRecord])
64|    -> std::result::Result<(i64, String), CozoError>
65|{
66|    let result = query(tx, "?[next,pending] := *native_container_sequence{key,next,pending}, key = 'default'", Params::new())?;
67|    let (next, pending) = match result.rows.as_slice() {
68|        [] if rows.is_empty() => {
69|            let marker = query(tx, "?[completed] := *schema_migrations{name,completed}, name = 'native-container-sequence-v1'", Params::new())?;
70|            if !marker.rows.is_empty() { return Err(err("native creation sequence is missing; refusing reset")); }
71|            (1, String::new())
72|        }
73|        [row] => (integer(row, 0)?, string(row, 1)?),
74|        _ => return Err(err("native creation sequence is missing or corrupt")),
75|    };
76|    let mut sorted = rows.iter().collect::<Vec<_>>();
77|    sorted.sort_by_key(|r| r.number);
78|    let mut expected = 1i64;
79|    for row in sorted {
80|        if row.number != expected
81|            || (row.number < next && row.phase != "complete")
82|            || (row.number == next && (row.phase == "complete" || row.request.operation_id != pending))
83|            || row.number > next
84|        { return Err(err("native creation history is incomplete; refusing sequence recovery")); }
85|        expected = expected.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
86|    }
87|    if next < 1 || (pending.is_empty() && expected != next)
88|        || (!pending.is_empty() && next.checked_add(1) != Some(expected))
89|    { return Err(err("native sequence and pending fence disagree")); }
90|    Ok((next, pending))
91|}
92|
93|fn put_sequence(tx: &MultiTransaction, next: i64, pending: &str) -> std::result::Result<(), CozoError> {
94|    query(tx, "?[key,next,pending] <- [['default',$next,$pending]] :put native_container_sequence {key => next,pending}",
95|        BTreeMap::from([("next".into(), dv_int(next)), ("pending".into(), DataValue::Str(pending.into()))]))?;
96|    query(tx, "?[name,completed] <- [['native-container-sequence-v1',true]] :put schema_migrations {name => completed}", Params::new())?;
97|    Ok(())
98|}
