100|impl CozoGraphShuttle {
101|    pub fn native_creation_records(&self) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
102|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
103|        let tx = self.db.multi_transaction(false);
104|        let rows = records(&tx)?;
105|        sequence(&tx, &rows)?;
106|        commit_checked(&tx)?;
107|        Ok(rows)
108|    }
109|
110|    /// `fresh` is the only permission to issue POST, returned after the barrier.
111|    /// Replays, including intent-only replays, may only read/reconcile.
112|    pub fn reserve_native_creation(&self, request: NativeCreationRequest, observed_names: &[String])
113|        -> std::result::Result<(NativeCreationRecord, bool), CozoError>
114|    {
115|        if self.identity_directory.is_none() { return Err(err("native allocation requires persistent Cozo")); }
116|        if uuid::Uuid::parse_str(&request.operation_id).map_or(true, |id| id.to_string() != request.operation_id)
117|            || request.actor_id.is_empty() || request.caller_session.is_empty() || request.caller_genesis.is_empty()
118|            || !matches!(request.owner_kind.as_str(), "identity" | "project" | "incus")
119|            || request.logical_target.is_empty() || request.schema_hash.is_empty() || !valid_root_repair_digest(&request.request_digest)
120|            || request.request_json.len() > 65536
121|        { return Err(err("invalid native creation intent")); }
122|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
123|        self.sync_identity_store()?;
124|        let tx = self.db.multi_transaction(true);
125|        let rows = records(&tx)?;
126|        let (next, pending) = sequence(&tx, &rows)?;
127|        // Existing labels do not acquire ownership or require a journal entry.
128|        // Only a collision with this allocation matters; never rename them or
129|        // reconstruct the persistent counter from a provider-side maximum.
130|        if let Some(row) = rows.iter().find(|row| row.request.operation_id == request.operation_id) {
131|            if row.request != request { return Err(err("native operation_id reused with different caller or request")); }
132|            commit_checked(&tx)?;
133|            return Ok((row.clone(), false));
134|        }
135|        if !pending.is_empty() { return Err(err("native creation unresolved; reconcile the owning operation before allocating another name")); }
136|        if request.owner_kind != "incus" && rows.iter().any(|row| row.request.owner_kind == request.owner_kind
137|            && row.request.logical_target == request.logical_target && observed_names.contains(&row.name))
138|        { return Err(err("logical target already has a native container; retain its binding")); }
139|        next.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
140|        let record = NativeCreationRecord { request, number: next, name: format!("ID-{next}"), phase: "intent".into(), native_uuid: String::new() };
141|        if observed_names.contains(&record.name) { return Err(err("native name collision")); }
142|        put(&tx, &record)?;
143|        put_sequence(&tx, next, &record.request.operation_id)?;
144|        commit_checked(&tx)?;
145|        self.sync_identity_store()?;
146|        Ok((record, true))
147|    }
148|
149|    pub fn bind_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str)
150|        -> std::result::Result<NativeCreationRecord, CozoError>
151|    {
152|        if uuid::Uuid::parse_str(native_uuid).map_or(true, |id| id.to_string() != native_uuid) {
153|            return Err(err("native creation readback lacks canonical UUID"));
154|        }
155|        self.update_native_creation(expected, native_uuid, false)
156|    }
157|
158|    /// Called only after complete canonical SHM publication. No abort/reset API.
159|    pub fn complete_native_creation(&self, expected: &NativeCreationRecord)
160|        -> std::result::Result<NativeCreationRecord, CozoError>
161|    {
162|        self.update_native_creation(expected, &expected.native_uuid, true)
163|    }
164|
165|    fn update_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str, complete: bool)
166|        -> std::result::Result<NativeCreationRecord, CozoError>
167|    {
168|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
169|        let tx = self.db.multi_transaction(true);
170|        let rows = records(&tx)?;
171|        let (next, pending) = sequence(&tx, &rows)?;
172|        let current = rows.iter().find(|r| r.request.operation_id == expected.request.operation_id)
173|            .ok_or_else(|| err("native creation intent disappeared"))?;
174|        if current != expected { return Err(err("native creation compare/exchange conflict")); }
175|        if current.phase == "complete" {
176|            if current.native_uuid != native_uuid { return Err(err("native UUID changed")); }
177|            commit_checked(&tx)?;
178|            self.sync_identity_store()?;
179|            return Ok(current.clone());
180|        }
181|        if pending != current.request.operation_id || next != current.number
182|            || (!current.native_uuid.is_empty() && current.native_uuid != native_uuid)
183|            || (complete && current.phase != "bound")
184|        { return Err(err("native creation fence or UUID changed")); }
185|        let mut updated = current.clone();
186|        updated.native_uuid = native_uuid.into();
187|        updated.phase = if complete { "complete" } else { "bound" }.into();
188|        put(&tx, &updated)?;
189|        if complete { put_sequence(&tx, next.checked_add(1).ok_or_else(|| err("native sequence exhausted"))?, "")?; }
190|        commit_checked(&tx)?;
191|        self.sync_identity_store()?;
192|        Ok(updated)
193|    }
