{"content":"1|//! MutationEngine-owned native name allocation and creation retry protection.
2|//! Names are human-facing; the creation journal is not a lifecycle authority.
3|//! No retry ever repeats POST.
4|use anyhow::{Context, Result, ensure};
5|use op_cozo_store::{NativeCreationRecord, NativeCreationRequest};
6|use op_plugins::state_plugins::incus::{self, IncusRootRepairBackend};
7|use serde_json::{Value, json};
8|use sha2::{Digest, Sha256};
9|use crate::mutation_engine::MutationEngine;
10|
11|pub(crate) async fn records(engine: &MutationEngine) -> Result<Vec<NativeCreationRecord>> {
12|    let cozo = engine.identity_sled_store()?.cozo().clone();
13|    Ok(tokio::task::spawn_blocking(move || cozo.native_creation_records()).await??)
14|}
15|
16|pub(crate) fn request(operation: &str, actor: &str, session: &str, genesis: &str,
17|    kind: &str, target: &str, body: Value) -> Result<NativeCreationRequest> {
18|    ensure!(body.is_object() && body.get("name").is_none(), "native name is server assigned");
19|    let plugin = match kind { "identity" => "identity_sled", "project" => "project", "incus" => "incus",
20|        _ => anyhow::bail!("unknown native owner") };
21|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
22|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
23|    let request_json = serde_json::to_string(&body)?;
24|    let request_digest = format!("{:x}", Sha256::digest(request_json.as_bytes()));
25|    Ok(NativeCreationRequest { operation_id: operation.into(), actor_id: actor.into(),
26|        caller_session: session.into(), caller_genesis: genesis.into(), owner_kind: kind.into(),
27|        logical_target: target.into(), schema_hash: pin.schema_hash, request_digest, request_json })
28|}
29|
30|async fn admit(engine: &MutationEngine, request: &NativeCreationRequest) -> Result<()> {
31|    let (plugin, method, capability) = match request.owner_kind.as_str() {
32|        "identity" => ("identity_sled", "prepare_container", "identity_sled.write"),
33|        "project" => ("project", "create", "project.create"),
34|        "incus" => ("incus", "create_instance", "cap.service.incus.instance.create@v1"),
35|        _ => anyhow::bail!("unknown native owner"),
36|    };
37|    crate::method_contract_admission::admit_compiled_method(plugin, method, Some(capability))?;
38|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
39|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
40|    ensure!(pin.schema_hash == request.schema_hash, "native creation seal changed; explicit reconciliation required");
41|    ensure!(crate::interceptor::load_capability_grants(&request.actor_id).contains(capability),
42|        "native creation requires current exact-principal grant");
43|    let current = engine.session_context_for_actor(&request.actor_id).await
44|        .context("native creation caller session missing")?;
45|    ensure!(current.session_id == request.caller_session && current.genesis_hex == request.caller_genesis,
46|        "native creation caller session changed");
47|    Ok(())
48|}
49|
50|/// Caller holds lifecycle (if applicable), then host observation lock. The
51|/// durable intent is committed and flushed before the sole POST permission.
52|pub(crate) async fn create_locked(engine: &MutationEngine, request: NativeCreationRequest)
53|    -> Result<(NativeCreationRecord, bool)> {
54|    admit(engine, &request).await?;
55|    let native = IncusRootRepairBackend::local();
56|    let before = native.default_project_state().await?;
57|    if request.owner_kind == "project" {
58|        let prior = records(engine).await?;
59|        ensure!(!before.instances.iter().any(|i|
60|            (i.name == request.logical_target || i.config.as_ref().is_some_and(|c|
61|                c.get("user.opdbus.project_id") == Some(&request.logical_target)))
62|            && !prior.iter().any(|r| r.name == i.name && r.request.operation_id == request.operation_id)),
63|            "existing project native binding must not be recreated");
64|    }
65|    let names = before.instances.iter().map(|i| i.name.clone()).collect::<Vec<_>>();
66|    let cozo = engine.identity_sled_store()?.cozo().clone();
67|    let (record, fresh) = tokio::task::spawn_blocking(move || cozo.reserve_native_creation(request, &names)).await??;
68|    // Any failure from here retains the fence, including definite provider
69|    // errors. An absent object is not proof that an earlier POST was rejected.
70|    if fresh {
71|        admit(engine, &record.request).await?;
72|        let mut body: Value = serde_json::from_str(&record.request.request_json)?;
73|        body["name"] = record.name.clone().into();
74|        body["config"]["user.opdbus.creation_operation"] = record.request.operation_id.clone().into();
75|        body["config"]["user.opdbus.creation_digest"] = record.request.request_digest.clone().into();
76|        incus::create_reserved_native(&body).await
77|            .context("native POST outcome requires reconciliation; reservation retained")?;
78|    }
79|    let record = reconcile_locked(engine, record).await?;
80|    Ok((record, !fresh))
81|}
82|
83|pub(crate) async fn reconcile_locked(engine: &MutationEngine, record: NativeCreationRecord)
84|    -> Result<NativeCreationRecord> {
85|    admit(engine, &record.request).await?;
86|    let native = IncusRootRepairBackend::local();
87|    let (raw, _) = native.instance(&record.name).await
88|        .context("reserved native instance absent or unreadable; POST will not be repeated")?;
89|    let body: Value = serde_json::from_str(&record.request.request_json)?;
90|    ensure!(raw["name"] == record.name && raw["type"] == body["type"]
91|        && raw["config"]["user.opdbus.creation_operation"] == record.request.operation_id
92|        && raw["config"]["user.opdbus.creation_digest"] == record.request.request_digest,
93|        "native creation ownership markers differ");
94|    if record.phase != "complete" {
95|        ensure!(raw["status"] == "Stopped" && raw["status_code"] == 102
96|            && raw["profiles"] == body["profiles"] && raw["devices"] == body["devices"],
97|            "native preparation is not the pinned stopped definition");
98|        if record.request.owner_kind == "identity" {
99|            ensure!(raw["expanded_config"]["security.privileged"] == "false"
100|                && raw["expanded_config"]["security.nesting"] == "false"
101|                && raw["expanded_config"]["boot.autostart"] == "false"
102|                && raw["expanded_config"]["raw.lxc"] == body["config"]["raw.lxc"],
103|                "expanded native identity security differs");
104|            let expanded = raw["expanded_devices"].as_object().context("expanded devices absent")?;
105|            ensure!(expanded.len() == 4 && expanded.get("root") == body["devices"].get("root")
106|                && expanded.get("runtime-run") == body["devices"].get("runtime-run")
107|                && expanded.get("fuse") == body["devices"].get("fuse")
108|                && expanded.get("lungs-socket-dir") == Some(&json!({"type":"disk", "source":"/run/opdbus/lungs",
109|                    "path":"/run/opdbus/lungs", "readonly":"true"})), "expanded identity devices differ");
110|        }
111|        for (key, value) in body["config"].as_object().context("creation config missing")? {
112|            ensure!(raw["config"].get(key) == Some(value), "native creation config differs");
113|        }
114|    }
115|    let native_uuid = raw["config"]["volatile.uuid"].as_str().context("native UUID absent")?.to_owned();
116|    ensure!(uuid::Uuid::parse_str(&native_uuid)?.to_string() == native_uuid, "noncanonical native UUID");
117|    let cozo = engine.identity_sled_store()?.cozo().clone();
118|    let pinned = record.clone();
119|    let bound = tokio::task::spawn_blocking(move || cozo.bind_native_creation(&pinned, &native_uuid)).await??;
120|    let snapshot = native.default_project_state().await?;
121|    let instance = snapshot.instances.iter().find(|i| i.name == bound.name)
122|        .context("created instance missing from full readback")?;
123|    ensure!(serde_json::to_value(instance)? == serde_json::to_value(incus::IncusPlugin::instance_from_native_metadata(raw)?)?,
124|        "native instance changed during full readback");
125|    crate::incus_observer::publish_repair_readback_locked(engine, &snapshot).await?;
126|    let cozo = engine.identity_sled_store()?.cozo().clone();
127|    Ok(tokio::task::spawn_blocking(move || cozo.complete_native_creation(&bound)).await??)
128|}
129|
130|pub(crate) async fn dispatch(engine: &MutationEngine, method: &str, args: &Value,
131|    actor: &str, session: Option<&str>, genesis: Option<&str>) -> Result<Value> {
132|    let session = session.context("native creation requires verified session")?.to_owned();
133|    let genesis = genesis.context("native creation requires verified genesis")?.to_owned();
134|    let engine = engine.clone();
135|    let method = method.to_owned();
136|    let args = args.clone();
137|    let actor = actor.to_owned();
138|    tokio::spawn(async move {
139|        let _host = engine.lock_host_observation().await;
140|        let (record, replayed) = if method == "create_instance" {
141|            let input: incus::CreateInstanceInput = serde_json::from_value(args)?;
142|            let body = incus::native_creation_body(&input)?;
143|            let request = request(&input.operation_id, &actor, &session, &genesis,
144|                "incus", &input.operation_id, body)?;
145|            create_locked(&engine, request).await?
146|        } else {
147|            let input: incus::ReconcileNativeCreationInput = serde_json::from_value(args)?;
148|            let record = records(&engine).await?.into_iter()
149|                .find(|r| r.request.operation_id == input.operation_id)
150|                .context("native creation operation not found")?;
151|            ensure!(record.request.owner_kind == "incus" && record.request.actor_id == actor
152|                && record.request.caller_session == session && record.request.caller_genesis == genesis,
153|                "native creation operation belongs to another owner");
154|            (reconcile_locked(&engine, record).await?, true)
155|        };
156|        Ok(json!({"name":record.name,"operation_id":record.request.operation_id,
157|            "native_uuid":record.native_uuid,"phase":record.phase,"replayed":replayed,
158|            "created":true,"changes":[]}))
159|    }).await.context("native creation owner failed; reconcile the same operation")?
