466|fn recovery_to_state(snapshot: &IdentityRecoverySnapshot) -> anyhow::Result<SledCacheState> {
467|    let mut ids = HashSet::new();
468|    let mut sleds = Vec::new();
469|    for revision in &snapshot.identities {
470|        anyhow::ensure!(
471|            ids.insert(revision.session_id.as_str()),
472|            "duplicate identity revision"
473|        );
474|        let Some(record) = &revision.record else {
475|            continue;
476|        };
477|        anyhow::ensure!(
478|            record.session_id == revision.session_id,
479|            "revision row mismatch"
480|        );
481|        if let Some(genesis) = &revision.genesis {
482|            anyhow::ensure!(
483|                genesis.session_id == revision.session_id,
484|                "genesis row mismatch"
485|            );
486|        }
487|        sleds.push(record_to_sled(record, revision.genesis.as_ref())?);
488|    }
489|    sleds.sort_by(|left, right| left.session_id.cmp(&right.session_id));
490|    let events = snapshot
491|        .events
492|        .iter()
493|        .map(event_from_record)
494|        .collect::<anyhow::Result<Vec<_>>>()?;
495|    Ok(SledCacheState { sleds, events })
